settings.global_custom_css:
#addonId {
  position: absolute;
  height: 500px;
  width: 100%;
  border-radius: 100%;
  background: linear-gradient(
            90deg,
            #fad0c4 0%,
            #fad0c4 1%,
            #ffd1ff 100%
        );
  filter: blur(54px) !important;
}
@media (max-width: 575px) {
#addonWrapper {
  max-width: 440px;
  margin: 0 auto;
}
}
